import { IPraia } from '@domain/db/entities/praia.entity';

export const PRAIA_CATALOG_VERSION = '2026-11-24.1';

type EntradaCatalogo = Pick<
    IPraia,
    | 'id'
    | 'slug'
    | 'nome'
    | 'municipio'
    | 'regiao'
    | 'latitude'
    | 'longitude'
    | 'precisaoCoordenada'
    | 'ambiente'
    | 'direcaoCostaInicioGraus'
    | 'direcaoCostaFimGraus'
    | 'exposicaoSwellEstatica'
    | 'acesso'
    | 'infraestrutura'
    | 'indicacaoEstatica'
    | 'perfilEstatico'
    | 'prioridade'
> &
    Partial<
        Pick<
            IPraia,
            | 'nomesAlternativos'
            | 'segmentoDe'
            | 'previsaoDe'
            | 'alertasEstruturais'
            | 'elegivelRecomendacao'
            | 'ativo'
            | 'requerBalneabilidadeRecente'
            | 'visivelCatalogo'
            | 'fonteLocalizacao'
            | 'revisadoEm'
            | 'revisadoPor'
        >
    >;

const FONTE_IMA = 'IMA — Sistema de Balneabilidade de Santa Catarina';
const FONTE_APROXIMADA = 'Catálogo editorial inicial — coordenada aproximada';
const FONTE_INDEFINIDA = 'Catálogo editorial inicial — ponto a definir';
const TRILHA = { codigo: 'acesso-trilha', mensagem: 'O acesso inclui trilha; avalie preparo, deslocamento e condições do percurso.' };
const SEM_ESTRUTURA = { codigo: 'sem-infraestrutura', mensagem: 'Não há infraestrutura confirmada no trecho; planeje alimentação, água e retorno.' };
const EMBARCACOES = { codigo: 'embarcacoes', mensagem: 'A presença de embarcações pode afetar o uso do trecho.' };
const FOZ = { codigo: 'foz-corrente', mensagem: 'Fozes e canais podem apresentar correntes e variação na qualidade da água.' };
const ACESSO_VALIDAR = { codigo: 'acesso-a-validar', mensagem: 'O acesso público e os limites do trecho precisam de validação local.' };
const BARCO = { codigo: 'acesso-barco', mensagem: 'O acesso depende de operação de barco e das condições da travessia.' };

function fonte(precisao: EntradaCatalogo['precisaoCoordenada']): string {
    if (precisao === 'oficial_ima') return FONTE_IMA;
    if (precisao === 'aproximada') return FONTE_APROXIMADA;
    if (precisao === 'ponto_a_definir') return FONTE_INDEFINIDA;
    return 'Validação de campo registrada no catálogo';
}

function entrada(dados: EntradaCatalogo): IPraia {
    return {
        nomesAlternativos: [],
        segmentoDe: null,
        previsaoDe: null,
        alertasEstruturais: [],
        elegivelRecomendacao: false,
        requerBalneabilidadeRecente: true,
        visivelCatalogo: true,
        revisadoEm: null,
        revisadoPor: null,
        ...dados,
        fonteLocalizacao: dados.fonteLocalizacao ?? fonte(dados.precisaoCoordenada),
        ativo:
            dados.ativo === true &&
            dados.elegivelRecomendacao === true &&
            dados.precisaoCoordenada === 'oficial_ima' &&
            dados.latitude !== null &&
            dados.longitude !== null,
    };
}

